[t]
  \KwIn{Evaluation benchmarks $B = \{b_{j} : j = 1, \ldots, m\} $, iteration count $n \in \mathbb{N}$}
  \KwOut{Improved agent system $A_{n}$}
  Initialise agent $A_{0}$\;
  \For {$i = 0, 1, \ldots, n-1$} {
    Evaluate $A_{i}$ on benchmarks $B$ and store in $p_{i}$\;
    Run $A_{\hat{i}}$ to generate $A_{i+1}$, using the archive of $A_{\le i}$
    and $p_{\le i}$, where $\hat{i} = \argmax_{j \in \{0, \ldots, i\}}p_{j}$\;
  }
  \Return $A_{n}$\;
  \caption{\label{algo:adas}Self-Referential Agent Improvement.}
